def _sql_literal(v: Any) -> str:
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, float):
        return repr(v) if math.isfinite(v) else f"'{v}'::float"   # 'nan' / 'inf' / '-inf'
    if isinstance(v, int):
        return str(v)
    return "'" + str(v).replace("'", "''") + "'"


def sql_dump(rows: list[dict[str, Any]], batch: int = 500) -> str:
    """Self-contained SQL backup: drop, create, insert every row, all in one transaction."""
    cols = [c.name for c in account_metrics.columns]
    out = ["-- Backup of account_metrics generated by scripts/setup_db.py --sql.",
           "-- Restore: psql \"$DATABASE_URL\" -f sql/account_metrics.sql",
           "BEGIN;", f"DROP TABLE IF EXISTS {account_metrics.name};", ddl()]
    for i in range(0, len(rows), batch):
        values = ",\n".join("(" + ", ".join(_sql_literal(r[c]) for c in cols) + ")" for r in rows[i:i + batch])
        out.append(f"INSERT INTO {account_metrics.name} ({', '.join(cols)}) VALUES\n{values};")
